# Construct cropped panels and punch same-color template shapes.
R,C=19,13
O=[[2]*C for _ in range(R)]
patterns={
  9:[[1,0,1],[1,1,1],[0,1,0]],
  6:[[0,1,1],[0,1,1],[1,0,0]],
  3:[[1,0,1],[0,1,1],[0,1,0]],
  4:[[1,1,1],[0,1,0],[0,1,0]],
}
# panel positions in the cropped output
for r0,color,c0 in [(1,9,1),(1,6,7),(7,3,1),(7,4,7)]:
    for dr in range(5):
        for dc in range(5): O[r0+dr][c0+dc]=color
    pat=patterns[color]
    for dr in range(3):
        for dc in range(3):
            if pat[dr][dc]: O[r0+1+dr][c0+1+dc]=2
print('\n'.join(' '.join(map(str,row)) for row in O))
